def H(s,k,en,ur,ps,**m): add(s,k,en,ur,ps,kind='heading',**m)
NOTE=' Diagrams are redrawn as simplified coded SVG with the printed labels. Watermark, border lines, page-edge shadows and handwriting are excluded.'
def fin(s,note):
    s['sourceNote']=note+NOTE; s['vocabulary']={}; save(s)
def bx(x,y,w,h,t,sz=11,fill='#fff'):
    return f'<rect x="{x}" y="{y}" width="{w}" height="{h}" fill="{fill}" stroke="#111" stroke-width="1.5"/>'+T(x+w/2,y+h/2+4,t,sz,'middle',700)
def el(cx,cy,rx,ry,t,sz=10,fill='#c9dca0'):
    return f'<ellipse cx="{cx}" cy="{cy}" rx="{rx}" ry="{ry}" fill="{fill}" stroke="#111"/>'+T(cx,cy+4,t,sz,'middle',700)
def dm(cx,cy,w,h,t,sz=10,fill='#9cc4e4'):
    return f'<polygon points="{cx},{cy-h} {cx+w},{cy} {cx},{cy+h} {cx-w},{cy}" fill="{fill}" stroke="#111" stroke-width="1.3"/>'+T(cx,cy+4,t,sz,'middle',700)
def ln(x1,y1,x2,y2):
    return f'<line x1="{x1}" y1="{y1}" x2="{x2}" y2="{y2}" stroke="#111" stroke-width="1.3"/>'
